target.css:
:root {
  --ink: #27363a;
  --muted: #6f7e7d;
  --line: #dce5df;
  --paper: #fffefa;
  --mint: #dff4e8;
  --mint-deep: #2d8768;
  --coral: #ffe0d8;
  --coral-deep: #bc5d4f;
  --lemon: #fff0b8;
  --lemon-deep: #a77917;
  --soft: #f4f7f3;
}

.fridge-console {
  box-sizing: border-box;
  width: 500px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--paper);
  color: var(--ink);
}

.console-header,
.brand-block,
.summary-card,
.panel-header,
.stock-row {
  display: flex;
  align-items: center;
}

.console-header {
  justify-content: space-between;
  margin-bottom: 12px;
}

.brand-block {
  gap: 10px;
}

.brand-mark {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 13px;
  background: var(--mint);
  font-size: 20px;
}

.brand-copy p,
.summary-card p,
.panel-header p,
.summary-card strong,
.stock-list {
  margin: 0;
}

.eyebrow {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
  line-height: 1.2;
  text-transform: uppercase;
}

h1,
h2 {
  margin: 2px 0 0;
  letter-spacing: -0.4px;
}

h1 {
  font-size: 20px;
  line-height: 1.1;
}

h2 {
  font-size: 16px;
  line-height: 1.1;
}

.shift-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 9px;
  border-radius: 999px;
  background: var(--soft);
  color: var(--mint-deep);
  font-size: 11px;
  font-weight: 800;
}

.shift-badge i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--mint-deep);
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-bottom: 12px;
}

.summary-card {
  min-height: 58px;
  gap: 8px;
  padding: 8px 9px;
  border-radius: 13px;
}

.card-icon {
  display: grid;
  width: 27px;
  height: 27px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 9px;
  background: var(--paper);
  font-size: 15px;
  font-weight: 800;
}

.summary-card p {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.1;
}

.summary-card strong {
  display: block;
  margin-top: 3px;
  font-size: 18px;
  line-height: 1;
}

.summary-card small {
  font-size: 10px;
  font-weight: 700;
}

.coral-card { background: var(--coral); }
.mint-card { background: var(--mint); }
.lemon-card { background: var(--lemon); }
.coral-card .card-icon { color: var(--coral-deep); }
.mint-card .card-icon { color: var(--mint-deep); }
.lemon-card .card-icon { color: var(--lemon-deep); }

.stock-panel {
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: var(--soft);
}

.panel-header {
  justify-content: space-between;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
}

.filter-button {
  padding: 6px 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--paper);
  color: var(--ink);
  font-size: 10px;
  font-weight: 800;
}

.filter-button span {
  margin-left: 5px;
  color: var(--muted);
}

.stock-list {
  padding: 3px 0 0;
  list-style: none;
}

.stock-row {
  gap: 8px;
  min-height: 28px;
  border-bottom: 1px solid var(--line);
  font-size: 11px;
}

.stock-row:last-child {
  border-bottom: 0;
}

.food-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.tomato-dot { background: var(--coral-deep); }
.milk-dot { background: var(--mint-deep); }
.bread-dot { background: var(--lemon-deep); }

.food-name {
  flex: 1;
  font-weight: 800;
}

.stock-count {
  color: var(--muted);
  font-size: 10px;
}

.status-tag {
  min-width: 48px;
  padding: 3px 5px;
  border-radius: 6px;
  text-align: center;
  font-size: 9px;
  font-weight: 800;
}

.urgent {
  background: var(--coral);
  color: var(--coral-deep);
}

.steady {
  background: var(--mint);
  color: var(--mint-deep);
}

